package com.hmdp.ai.runtime.node;
import com.fasterxml.jackson.databind.*;import com.hmdp.ai.domain.run.AgentRunOutput;import com.hmdp.ai.domain.workflow.WorkflowNodeType;import com.hmdp.ai.runtime.agent.AgentOutputValidator;import org.springframework.stereotype.Component;import java.util.*;
@Component public class OutputNodeExecutor implements NodeExecutor {private final AgentOutputValidator validator;private final ObjectMapper mapper;public OutputNodeExecutor(AgentOutputValidator v,ObjectMapper m){validator=v;mapper=m;}public Set<WorkflowNodeType>supportedTypes(){return Collections.singleton(WorkflowNodeType.OUTPUT_VALIDATION);}public NodeExecutionResult execute(NodeExecutionContext c){Object v=c.getVariables().get("agentOutput");if(!(v instanceof AgentRunOutput))return NodeExecutionResult.failure("WORKFLOW_OUTPUT_REQUIRED",false);validator.validate(c.getAgent().getVersion().getOutputSchema(),(AgentRunOutput)v);return NodeExecutionResult.success(mapper.valueToTree(v),null,null);}}
